import numpy as np


def heilbronn_triangle11() -> np.ndarray:
    """Deterministic annealing followed by signed maximin constrained polishing."""
    n = 11
    h = np.sqrt(3.0) / 2.0
    rng = np.random.default_rng(11011)

    triples = np.array(
        [(i, j, k) for i in range(n) for j in range(i + 1, n)
         for k in range(j + 1, n)],
        dtype=np.int32,
    )

    def determinants(points):
        a = points[triples[:, 0]]
        b = points[triples[:, 1]]
        c = points[triples[:, 2]]
        return ((b[:, 0] - a[:, 0]) * (c[:, 1] - a[:, 1])
                - (b[:, 1] - a[:, 1]) * (c[:, 0] - a[:, 0]))

    def objective(points):
        return float(np.min(np.abs(determinants(points))))

    def inside(points):
        x, y = points[:, 0], points[:, 1]
        return bool(np.all((x >= 0.0) & (y >= 0.0) &
                           (y <= np.sqrt(3.0) * x) &
                           (y <= np.sqrt(3.0) * (1.0 - x))))

    def random_points():
        u = rng.random(n)
        v = rng.random(n)
        mask = u + v > 1.0
        u[mask] = 1.0 - u[mask]
        v[mask] = 1.0 - v[mask]
        return np.column_stack((
            v + 0.5 * (1.0 - u - v),
            h * (1.0 - u - v),
        ))

    best = None
    best_value = -1.0
    endpoints = []

    # This preserves the robust global component of the parent construction.
    for _ in range(24):
        points = random_points()
        value = objective(points)
        for iteration in range(40000):
            q = iteration / 40000.0
            scale = 0.16 * (1.0 - q) ** 1.7 + 0.001
            idx = int(rng.integers(n))
            trial = points.copy()
            trial[idx] += rng.normal(0.0, scale, 2)
            if not inside(trial):
                continue
            trial_value = objective(trial)
            temperature = max(1e-9, 0.0025 * (1.0 - q) ** 1.25)
            if (trial_value >= value or
                    rng.random() < np.exp((trial_value - value) / temperature)):
                points, value = trial, trial_value
                if value > best_value:
                    best, best_value = points.copy(), value
        endpoints.append((value, np.asarray(points, dtype=np.float64).copy()))
        if len(endpoints) > 6:
            endpoints.sort(key=lambda item: item[0], reverse=True)
            del endpoints[6:]

    # Barycentric cluster crossover between the strongest annealing endpoints.
    # Each hybrid keeps seven points from one parent and replaces a coherent
    # four-point barycentric neighborhood using a second parent.
    if len(endpoints) >= 2:
        vertices = np.array(
            [[0.0, 0.0], [1.0, 0.0], [0.5, h]], dtype=np.float64
        )

        def to_barycentric(points):
            points = np.asarray(points, dtype=np.float64)
            return np.column_stack((
                1.0 - points[:, 0] - points[:, 1] / h,
                points[:, 0] - points[:, 1] / (2.0 * h),
                points[:, 1] / h,
            ))

        def from_barycentric(bary):
            bary = np.asarray(bary, dtype=np.float64)
            return bary @ vertices

        def canonical_key(points):
            bary = to_barycentric(points)
            transforms = []
            for shift in range(3):
                transforms.append(np.roll(bary, shift, axis=1))
            reflected = bary[:, [0, 2, 1]]
            for shift in range(3):
                transforms.append(np.roll(reflected, shift, axis=1))
            keys = []
            for transformed in transforms:
                ordered = np.sort(transformed, axis=0)
                keys.append(tuple(np.round(ordered.ravel(), 14)))
            return min(keys)

        canonical = sorted(
            endpoints[:6],
            key=lambda item: (canonical_key(item[1]), -item[0]),
        )
        parents = [item[1] for item in canonical[:3]]
        hybrids = []

        for first_index in range(len(parents)):
            for second_index in range(first_index + 1, len(parents)):
                first = np.asarray(
                    parents[first_index], dtype=np.float64
                ).copy()
                second = np.asarray(
                    parents[second_index], dtype=np.float64
                ).copy()
                if first.shape != (n, 2) or second.shape != (n, 2):
                    continue

                first_bary = to_barycentric(first)
                second_bary = to_barycentric(second)
                distances = np.sum(
                    (first_bary[:, None, :] - first_bary[None, :, :]) ** 2,
                    axis=2,
                )

                for anchor in range(n):
                    nearest = np.argsort(distances[anchor])[:4]
                    target = first_bary[nearest]
                    chosen = []
                    available = list(range(n))
                    for location in target:
                        if not available:
                            break
                        pick = min(
                            available,
                            key=lambda index: float(
                                np.sum((second_bary[index] - location) ** 2)
                            ),
                        )
                        chosen.append(pick)
                        available.remove(pick)
                    if len(chosen) != 4:
                        continue

                    hybrid_bary = first_bary.copy()
                    hybrid_bary[nearest] = second_bary[chosen]
                    hybrid_bary = np.maximum(hybrid_bary, 1e-12)
                    hybrid_bary /= hybrid_bary.sum(
                        axis=1, keepdims=True
                    )
                    hybrid = from_barycentric(hybrid_bary)
                    if hybrid.shape == (n, 2) and inside(hybrid):
                        hybrids.append((objective(hybrid), hybrid.copy()))

        if hybrids:
            endpoints.extend(hybrids)
            endpoints.sort(key=lambda item: item[0], reverse=True)
            endpoints = endpoints[:6]
            for value, points in endpoints:
                if value > best_value:
                    best = np.asarray(points, dtype=np.float64).copy()
                    best_value = float(value)

    if best is None:
        return random_points().astype(np.float64)

    # SLSQP is optional so the construction still executes on minimal NumPy setups.
    try:
        from scipy.optimize import minimize

        """Polish the three best annealing endpoints in separate sign cells."""
        ranked = sorted(endpoints, key=lambda item: item[0], reverse=True)
        selected = []
        for value, points in ranked:
            candidate = np.asarray(points, dtype=np.float64)
            if candidate.shape != (n, 2) or not np.all(np.isfinite(candidate)):
                continue
            if not any(np.max(np.abs(candidate - old)) < 1e-10
                       for _, old in selected):
                selected.append((float(value), candidate.copy()))
            if len(selected) == 6:
                break

        vertices = np.array(
            [[0.0, 0.0], [1.0, 0.0], [0.5, h]], dtype=np.float64
        )

        for endpoint_value, seed in selected:
            seed = np.asarray(seed, dtype=np.float64).copy()
            signs = np.sign(determinants(seed))
            signs[signs == 0.0] = 1.0
            x0 = np.concatenate((
                seed.ravel(), [max(0.0, endpoint_value * 0.999)]
            ))

            def constraints(z, signs=signs):
                p = z[:-1].reshape(n, 2)
                t = z[-1]
                x, y = p[:, 0], p[:, 1]
                edge = np.concatenate((
                    x, y, np.sqrt(3.0) * x - y,
                    np.sqrt(3.0) * (1.0 - x) - y,
                ))
                return np.concatenate((edge, signs * determinants(p) - t))

            candidates = [x0]
            bary = np.column_stack((
                1.0 - seed[:, 0] - seed[:, 1] / h,
                seed[:, 0] - seed[:, 1] / (2.0 * h),
                seed[:, 1] / h,
            ))
            bary = np.maximum(bary, 2e-8)
            bary /= bary.sum(axis=1, keepdims=True)
            projected = bary @ vertices
            candidates[0] = np.concatenate((
                projected.ravel(),
                [max(0.0, min(1.0, endpoint_value * 0.999))]
            ))

            for z in candidates:
                result = minimize(
                    lambda q: -q[-1],
                    z,
                    method="SLSQP",
                    bounds=[(0.0, 1.0)] * 22 + [(0.0, 1.0)],
                    constraints={"type": "ineq", "fun": constraints},
                    options={"maxiter": 900, "ftol": 1e-11, "disp": False},
                )
                if result.x is None:
                    continue
                p = result.x[:-1].reshape(n, 2)
                value = objective(p)
                if inside(p) and np.all(np.isfinite(p)) and value > best_value:
                    best, best_value = p.copy(), value
    except Exception:
        pass

    return np.asarray(best, dtype=np.float64)
